def solve(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    from collections import Counter
    cnt=Counter(x for r_ in g for x in r_)
    markers=[(i,j,g[i][j]) for i in range(h) for j in range(w) if cnt[g[i][j]]==min(cnt.values())]
    mc=markers[0][2]
    rs=[i for i,j,_ in markers]; cs=[j for _,j,_ in markers]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=[r_[:] for r_ in g]
    for j in range(c0,c1+1):
        for i in (r0,r1):
            if out[i][j]==mc: out[i][j]=2
    for i in range(r0,r1+1):
        for j in (c0,c1):
            if out[i][j]==mc: out[i][j]=2
    return out
for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    ok=solve(G[k+' input'])==G[k+' output']
    print(k, ok)
print(json.dumps(solve(G['Test input'])))

