def solve(g, K=3):
    h=len(g); w=len(g[0])
    cnt=collections.Counter(x for r_ in g for x in r_)
    mc=min(cnt,key=cnt.get)
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==mc]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts)
    c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    out=[r_[:] for r_ in g]
    # bbox ring
    for j in range(c0,c1+1):
        for i in (r0,r1):
            if out[i][j]==mc: continue
            out[i][j]=2
    for i in range(r0,r1+1):
        for j in (c0,c1):
            if out[i][j]==mc: continue
            out[i][j]=2
    # gap fills
    for i in range(h):
        mk=[j for j in range(w) if g[i][j]==mc]
        for a,b in zip(mk,mk[1:]):
            if b-a-1<=K:
                for j in range(a+1,b):
                    if out[i][j]!=mc: out[i][j]=2
    for j in range(w):
        mk=[i for i in range(h) if g[i][j]==mc]
        for a,b in zip(mk,mk[1:]):
            if b-a-1<=K:
                for r in range(a+1,b):
                    if out[r][j]!=mc: out[r][j]=2
    return out
